<?php
declare(strict_types=1);
require_once __DIR__.'/rules.php';require_once __DIR__.'/schema.php';
function headers_private(): void {header('X-Content-Type-Options: nosniff');header('X-Frame-Options: DENY');header('Referrer-Policy: strict-origin-when-cross-origin');header('Cache-Control: no-store');}
function json_response(mixed $data,int $status=200): never {http_response_code($status);header('Content-Type: application/json; charset=utf-8');echo json_encode($data,JSON_UNESCAPED_UNICODE|JSON_INVALID_UTF8_SUBSTITUTE|JSON_THROW_ON_ERROR);exit;}
class App {
 public PDO $db;public array $config;public string $storage;public string $base;public ?array $user=null;public ?string $session=null;public string $csrf='';
 public function __construct(public string $private){umask(0077);date_default_timezone_set('Asia/Ho_Chi_Minh');$file=$private.'/config.php';if(!is_file($file))fail('Chưa cấu hình: sao chép nhansu-private/config.example.php thành config.php và nhập database riêng.',503);$this->config=require $file;$url=parse_url($this->config['app_url']??'');if(!$url||!isset($url['host'])||!in_array($url['scheme']??'',['http','https'],true)||isset($url['user'])||isset($url['pass'])||isset($url['query'])||isset($url['fragment']))fail('app_url không hợp lệ trong config.php.',503);$this->base=rtrim($url['path']??'','/');if($this->base!==''&&!preg_match('~^/[A-Za-z0-9/_-]+$~D',$this->base))fail('Đường dẫn ứng dụng không hợp lệ.',503);if($url['scheme']!=='https'&&!in_array($url['host'],['127.0.0.1','localhost'],true))fail('Cần HTTPS cho camera và GPS.',503);$prefix=$this->config['table_prefix']??'';if(!preg_match('/^[a-z][a-z0-9_]{1,20}$/D',$prefix)||str_starts_with($prefix,'wp_'))fail('Dùng tiền tố bảng riêng, không dùng wp_.',503);
 $doc=realpath($_SERVER['DOCUMENT_ROOT']??'');$real=realpath($private);if(PHP_SAPI!=='cli'&&$doc&&($real===$doc||str_starts_with($real,$doc.DIRECTORY_SEPARATOR)))fail('Thư mục nhansu-private phải nằm ngoài public_html.',503);$this->storage=$private.'/storage';foreach(['','/backups','/cache'] as $dir)if(!is_dir($this->storage.$dir))mkdir($this->storage.$dir,0700,true);
 try{$this->db=new PDO('mysql:host='.$this->config['db_host'].';port='.(int)$this->config['db_port'].';dbname='.$this->config['db_name'].';charset=utf8mb4',$this->config['db_user'],$this->config['db_password'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_EMULATE_PREPARES=>false,PDO::ATTR_STRINGIFY_FETCHES=>false,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);$this->db->exec("SET time_zone='+00:00'");$this->initialize();}catch(PDOException $e){error_log('Nhansu database error '.$e->getCode());fail('Chưa kết nối được database riêng. Kiểm tra config.php và quyền MySQL.',503);}
 if(function_exists('load_legacy_event_log'))load_legacy_event_log($this);
 if(!$this->one('SELECT id FROM {{users}} LIMIT 1')&&!is_file($this->storage.'/setup-token'))file_put_contents($this->storage.'/setup-token',bin2hex(random_bytes(24)),LOCK_EX);
 }
 public function sql(string $sql): string {return preg_replace_callback('/\{\{([a-z_]+)\}\}/',function($m){if(!array_key_exists($m[1],schema()))throw new RuntimeException('Unknown table');return '`'.$this->config['table_prefix'].$m[1].'`';},$sql);}
 public function run(string $sql,array $params=[]): PDOStatement {$s=$this->db->prepare($this->sql($sql));foreach(array_values($params) as $i=>$v)$s->bindValue($i+1,$v,is_int($v)?PDO::PARAM_INT:($v===null?PDO::PARAM_NULL:PDO::PARAM_STR));$s->execute();return $s;}
 public function all(string $sql,array $params=[]): array {return $this->run($sql,$params)->fetchAll();}
 public function one(string $sql,array $params=[]): ?array {return $this->run($sql,$params)->fetch()?:null;}
 public function scalar(string $sql,array $params=[]): mixed {return $this->run($sql,$params)->fetchColumn();}
 public function initialize(): void {$tables=$this->db->query('SHOW TABLES')->fetchAll(PDO::FETCH_COLUMN);foreach($tables as $table)if(!str_starts_with($table,$this->config['table_prefix']))fail('Database đang có bảng của ứng dụng khác. Hãy tạo database mới riêng cho nhân sự; không dùng database WordPress.',503);if(in_array($this->config['table_prefix'].'meta',$tables,true)&&$this->scalar("SELECT value FROM {{meta}} WHERE `key`='schema_version'")==='5'&&$this->meta('schema_fingerprint')===hash('sha256',json_encode(schema(),JSON_THROW_ON_ERROR))&&!array_diff(array_map(fn($t)=>$this->config['table_prefix'].$t,array_keys(schema())),$tables))return;$lock=$this->config['table_prefix'].'install';if((int)$this->scalar('SELECT GET_LOCK(?,10)',[$lock])!==1)fail('Đang khởi tạo ứng dụng. Thử lại sau.',503);try{foreach(schema() as $table=>$definition)$this->db->exec('CREATE TABLE IF NOT EXISTS `'.$this->config['table_prefix'].$table.'` ('.$definition.') ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci');foreach(['source_ref'=>"VARCHAR(200) NULL UNIQUE",'source_label'=>"VARCHAR(150) NOT NULL DEFAULT ''",'date_precision'=>"VARCHAR(16) NOT NULL DEFAULT 'day'",'original_date'=>"VARCHAR(100) NOT NULL DEFAULT ''",'end_month'=>"VARCHAR(7) NOT NULL DEFAULT ''",'end_date'=>"VARCHAR(10) NOT NULL DEFAULT ''",'related_names'=>"VARCHAR(300) NOT NULL DEFAULT ''",'rule_id'=>"CHAR(36) NULL",'rule_code'=>"VARCHAR(30) NOT NULL DEFAULT ''",'rule_name'=>"VARCHAR(200) NOT NULL DEFAULT ''"] as $column=>$definition)if(!in_array($column,array_column($this->all('SHOW COLUMNS FROM {{event_log}}'),'Field'),true))$this->run('ALTER TABLE {{event_log}} ADD COLUMN `'.$column.'` '.$definition);foreach(['deposit_label','received_label'] as $column)if(!in_array($column,array_column($this->all('SHOW COLUMNS FROM {{shoot_bookings}}'),'Field'),true))$this->run('ALTER TABLE {{shoot_bookings}} ADD COLUMN `'.$column."` VARCHAR(50) NOT NULL DEFAULT '' AFTER note");if(!in_array('sheet_fields_json',array_column($this->all('SHOW COLUMNS FROM {{shoot_bookings}}'),'Field'),true))$this->run('ALTER TABLE {{shoot_bookings}} ADD COLUMN sheet_fields_json MEDIUMTEXT NULL AFTER received_label');if(!in_array('require_photo',array_column($this->all('SHOW COLUMNS FROM {{tasks}}'),'Field'),true))$this->run('ALTER TABLE {{tasks}} ADD COLUMN require_photo TINYINT NOT NULL DEFAULT 0 AFTER due_at');if(!in_array('template_id',array_column($this->all('SHOW COLUMNS FROM {{tasks}}'),'Field'),true))$this->run('ALTER TABLE {{tasks}} ADD COLUMN template_id CHAR(36) NULL,ADD COLUMN task_day VARCHAR(10) NULL,ADD UNIQUE KEY task_daily(template_id,task_day)');$this->run("INSERT IGNORE INTO {{meta}} (`key`,value) VALUES('write_lock','1')");$this->meta('schema_version','5');$this->meta('schema_fingerprint',hash('sha256',json_encode(schema(),JSON_THROW_ON_ERROR)));}finally{$this->run('SELECT RELEASE_LOCK(?)',[$lock]);}}
 public function meta(string $key,?string $value=null): ?string {if($value!==null){$this->run('INSERT INTO {{meta}} (`key`,value) VALUES(?,?) ON DUPLICATE KEY UPDATE value=VALUES(value)',[$key,$value]);return $value;}return $this->scalar('SELECT value FROM {{meta}} WHERE `key`=?',[$key])?:null;}
 public function tx(callable $fn): mixed {if($this->db->inTransaction())return $fn();$this->db->beginTransaction();try{$this->run("SELECT value FROM {{meta}} WHERE `key`='write_lock' FOR UPDATE");$result=$fn();$this->db->commit();return $result;}catch(Throwable $e){if($this->db->inTransaction())$this->db->rollBack();throw $e;}}
 public function safe(array $u): array {return array_intersect_key($u,array_flip(['id','name','email','role']));}
 public function authenticate(): void {$token=$_COOKIE['AG_NHANSU_SESSION']??'';if(!is_string($token)||!preg_match('/^[a-f0-9]{64}$/D',$token))fail('Vui lòng đăng nhập.',401);$this->session=hash('sha256',$token);$row=$this->one("SELECT u.*,s.csrf FROM {{users}} u JOIN {{sessions}} s ON s.user_id=u.id WHERE s.token=? AND s.expires>? AND u.archived=0 AND u.status!='inactive'",[$this->session,now_ms()]);if(!$row)fail('Vui lòng đăng nhập.',401);$this->csrf=$row['csrf'];unset($row['csrf']);$this->user=$row;}
 public function requireManager(): void {if(!in_array($this->user['role'],['admin','manager'],true))fail('Bạn không có quyền truy cập.',403);}
 public function requireAdmin(): void {if($this->user['role']!=='admin')fail('Chỉ Admin được thực hiện thao tác này.',403);}
 public function cookie(string $token,int $expires): void {setcookie('AG_NHANSU_SESSION',$token,['expires'=>$expires,'path'=>$this->base?:'/','secure'=>parse_url($this->config['app_url'],PHP_URL_SCHEME)==='https','httponly'=>true,'samesite'=>'Strict']);}
 public function audit(int $target,string $action,?int $actor=null): void {$this->run('INSERT INTO {{employee_audit}}(actor_id,user_id,action,time) VALUES(?,?,?,?)',[$actor??$this->user['id'],$target,$action,now_ms()]);}
 public function employees(bool $archived=false): array {return $this->all('SELECT u.id,u.name,u.email,u.role,u.employee_code,u.status,u.archived,'.implode(',',array_map(fn($f)=>'u.'.$f,PROFILE_FIELDS)).',COALESCE(s.monthly_salary,8000000) monthly_salary FROM {{users}} u LEFT JOIN {{salaries}} s ON s.user_id=u.id'.($archived?'':' WHERE u.archived=0').' ORDER BY u.id DESC');}
 public function createEmployee(array $b,int $actor): int {$this->run('INSERT INTO {{users}}(name,email,password,role,employee_code,status,notes) VALUES(?,?,?,?,?,?,?)',[$b['name'],$b['email'],password_hash($b['password'],PASSWORD_DEFAULT),$b['role'],'pending-'.bin2hex(random_bytes(10)),$b['status'],$b['notes']]);$id=(int)$this->db->lastInsertId();$this->run('UPDATE {{users}} SET employee_code=?,'.implode(',',array_map(fn($f)=>$f.'=?',PROFILE_FIELDS)).' WHERE id=?',['NV'.str_pad((string)$id,4,'0',STR_PAD_LEFT),...array_map(fn($f)=>$b[$f],PROFILE_FIELDS),$id]);$this->run('INSERT INTO {{salaries}} VALUES(?,?)',[$id,$b['monthly_salary']]);$this->audit($id,'create',$actor);return $id;}
 public function events(?int $id=null): array {return $this->all('SELECT e.id,e.user_id,e.type,e.time,e.distance,e.accuracy,e.shift,e.work_date,e.ot_confirmed_at,e.source,e.recorded_by,e.recorded_at,e.reason,(SELECT name FROM {{users}} WHERE id=e.recorded_by) recorded_by_name,(e.photo_jpeg IS NOT NULL) has_photo,u.name,u.email FROM {{events}} e JOIN {{users}} u ON u.id=e.user_id'.($id!==null?' WHERE e.user_id=?':'').' ORDER BY e.time,e.id',$id!==null?[$id]:[]);}
 public function assertOpen(int $time): void {if($this->closure(substr(local_day($time),0,7)))fail('Tháng này đã chốt lương. Admin cần mở lại trước khi thay đổi công hoặc hoa hồng.',409);}
 public function closure(string $month): ?array {return $this->one('SELECT * FROM {{payroll_closures}} WHERE month=? AND reopened_at IS NULL',[$month]);}
 public function summaries(string $month): array {$rows=[];foreach($this->all('SELECT id,name,email,role FROM {{users}} ORDER BY name') as $p){$w=$this->one('SELECT monthly_salary FROM {{salaries}} WHERE user_id=?',[$p['id']]);$rows[]=array_merge($p,summary($this->events($p['id']),$month,$w['monthly_salary']??8000000,$this->all('SELECT * FROM {{commissions}} WHERE user_id=?',[$p['id']])));}return $rows;}
 public function monthly(string $month): array {valid_month($month);$closed=$this->closure($month);$rows=$closed?json_decode($closed['rows_json'],true,512,JSON_THROW_ON_ERROR):$this->summaries($month);if($this->user['role']==='employee')$rows=array_values(array_map(fn($p)=>array_merge(array_intersect_key($p,array_flip(['id','name'])),visible_summary($this->user,$p)),array_filter($rows,fn($p)=>$p['id']===$this->user['id'])));if(function_exists('kpi_month_deductions')){$kpi=kpi_month_deductions($this,$month);foreach($rows as &$p){$p['kpi_quota']=KPI_MONTHLY_POINTS;$p['kpi_deducted']=$kpi[$p['id']]??0;$p['kpi_left']=KPI_MONTHLY_POINTS-$p['kpi_deducted'];}unset($p);}return ['month'=>$month,'rows'=>$rows,'closed'=>(bool)$closed,'closed_at'=>$closed['closed_at']??null,'closed_by'=>$closed['closed_by']??null];}
 public function target(int $id,bool $inactive=false): array {$u=$this->one('SELECT * FROM {{users}} WHERE id=?',[$id]);if(!$u||(!$inactive&&($u['archived']||$u['status']==='inactive')))fail('Nhân viên không tồn tại hoặc đã nghỉ.');authorize_edit($this->user,$u);return $u;}
 public function insertEvent(array $b,int $id,bool $manual): int {$time=$b['time']??now_ms();$this->assertOpen($time);$all=$this->events($id);$prior=array_values(array_filter($all,fn($e)=>$e['time']<=$time));$decision=attendance_decision($prior,$b['shift'],$time,$manual);if($decision['type']!==$b['type'])fail('Trạng thái ca đã thay đổi. Vui lòng tải lại; cần chấm vào trước rồi mới chấm ra.',409);if($b['shift']==='ot'&&$b['type']==='in'&&($b['ot_confirmed']??false)!==true)fail('Bạn phải xác nhận thực sự làm OT trước khi bắt đầu.');
 if($manual){$later=array_filter($all,fn($e)=>$e['time']>=$time&&($b['shift']==='ot'||$e['shift']===$b['shift']&&$e['work_date']===local_day($time)));if($later)fail('Đã có lượt công mới hơn. Hãy bổ sung theo thứ tự thời gian.',409);$distance=null;$accuracy=null;$photo=null;}else{$distance=position_distance($b['position']??null,$this->one('SELECT * FROM {{settings}} WHERE id=1'),now_ms());$accuracy=$b['position']['accuracy'];foreach(array_reverse($all) as $e)if($e['shift']===$b['shift']){if($time-$e['time']<30000)fail('Vui lòng đợi 30 giây trước lần chấm tiếp theo.',409);break;}$photo=normalize_photo($b['photo']??null);}
 if(in_array($b['shift'],['day_first','day_second'],true)&&$b['type']==='in'&&function_exists('freeze_booking_shift'))freeze_booking_shift($this,$id,local_day($time),$b['shift']);
 $this->run('INSERT INTO {{events}}(user_id,type,time,distance,accuracy,shift,work_date,ot_confirmed_at,photo_jpeg,source,recorded_by,recorded_at,reason) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)',[$id,$b['type'],$time,$distance,$accuracy,$b['shift'],$decision['workDate'],$b['shift']==='ot'&&$b['type']==='in'?now_ms():null,$photo,$manual?'manual':'self',$this->user['id'],now_ms(),$manual?$b['reason']:'']);$event=(int)$this->db->lastInsertId();if($manual)$this->audit($id,'manual_attendance');return $event;}
}
